"""Build or check the complete, executable schema reference from migrations."""
from pathlib import Path
import argparse
import hashlib


ROOT = Path(__file__).resolve().parents[1]


def render():
    parts = [
        "-- Generated by python3 scripts/export_schema.py; edit versioned migrations.\n",
        "-- Run against a NEW database only. Application upgrades use the migration runner.\n",
        (ROOT / "src-tauri/db/connection.sql").read_text(encoding="utf-8"),
    ]
    for path in sorted((ROOT / "src-tauri/migrations").glob("*.sql")):
        source = path.read_text(encoding="utf-8")
        version = int(path.name.split("_")[0])
        checksum = hashlib.sha256(source.encode()).hexdigest()
        parts.extend([
            f"\n-- Migration: {path.name}\nBEGIN IMMEDIATE;\n", source,
            f"\nINSERT INTO schema_migrations(version, name, sha256) VALUES ({version}, '{path.name}', '{checksum}');\n",
            "COMMIT;\n",
        ])
    parts.append("\nPRAGMA foreign_key_check;\nPRAGMA integrity_check;\n")
    return "".join(parts)


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--check", action="store_true", help="Fail if docs/schema.sql differs from migrations")
    args = parser.parse_args()
    destination = ROOT / "docs/schema.sql"
    expected = render()
    if args.check:
        if not destination.exists() or destination.read_text(encoding="utf-8") != expected:
            raise SystemExit("Schema reference is stale. Run python3 scripts/export_schema.py")
        print("Schema reference matches all versioned migrations.")
    else:
        destination.parent.mkdir(parents=True, exist_ok=True)
        destination.write_text(expected, encoding="utf-8")
        print(f"Wrote {destination.relative_to(ROOT)}")


if __name__ == "__main__":
    main()
